'use strict';
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang='pl';try{lang=new URLSearchParams(location.search).get('lang')||localStorage.getItem('agnieszka-language')||'pl';}catch{}
lang=lang==='uk'?'uk':'pl';
// 13.11.2026: V2 is the primary home page; V1 stays available through the version switch and ?v=1.
let version='2';
try{version=new URLSearchParams(location.search).get('v')||localStorage.getItem('agnieszka-home-version')||'2';}catch{}
version=version==='1'?'1':'2';
try{localStorage.setItem('agnieszka-home-version',version);}catch{}
const tr=(pl,uk)=>lang==='uk'?uk:pl;
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 12h15M13 5l7 7-7 7"/></svg>';
const menuIcon='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 8h16M4 16h16"/></svg>';
const bookButton=(label,id='help',style='')=>`<button class="button ${style}" data-book="${esc(id)}">${label}<span class="arrow">${arrow}</span></button>`;
function header(){return `<a class="skip" href="#main">${tr('Przejdź do treści','Перейти до вмісту')}</a><header class="site-header"><a class="brand" href="/#top">agnieszka clarity</a><nav class="nav-links" aria-label="${tr('Menu główne','Головне меню')}"><a href="/#o-mnie">${tr('O mnie','Про мене')}</a><a href="/#sesje">${tr('Sesje 1:1','Сесії 1:1')}</a><a href="/#joga">${tr('Studio Jogi','Студія йоги')}</a><a href="/warsztaty/">${tr('Warsztaty','Воркшопи')}</a><a href="/sklep/">${tr('Sklep','Магазин')}</a><a href="/#najblizsze">${tr('Wydarzenia','Події')}</a></nav><button class="language" data-language aria-label="${tr('Zmień język na ukraiński','Перемкнути на польську')}">PL / UK</button><button class="button nav-cta" data-book="help">${tr('Umów sesję','Записатися')}</button><button class="menu-toggle" aria-label="${tr('Otwórz menu','Відкрити меню')}" aria-expanded="false">${menuIcon}</button></header><nav class="mobile-nav" aria-label="${tr('Menu mobilne','Мобільне меню')}"><a href="/#o-mnie">${tr('O mnie','Про мене')}</a><a href="/#sesje">${tr('Sesje 1:1','Сесії 1:1')}</a><a href="/#joga">${tr('Studio Jogi','Студія йоги')}</a><a href="/warsztaty/">${tr('Warsztaty','Воркшопи')}</a><a href="/sklep/">${tr('Sklep','Магазин')}</a><a href="/#najblizsze">${tr('Wydarzenia','Події')}</a><button class="button" data-book="help">${tr('Umów sesję','Записатися')}</button></nav>`;}
function homeHero(){return `<section class="hero" aria-labelledby="hero-title"><img class="hero-photo" src="/assets/hero-open-sky.png" width="1706" height="922" alt="${tr('Kobieta z otwartymi ramionami nad wodą','Жінка з розкритими руками біля води')}" fetchpriority="high"><h1 id="hero-title"><span>${tr('Zatrzymaj się.','Зупинись.')}</span><span>${tr('Poczuj siebie.','Відчуй себе.')}</span></h1><div class="hero-intro"><p class="hero-methods">${tr('Sesje 1:1 · Joga · Medytacja','Сесії 1:1 · Йога · Медитація')}</p><p>${tr('Przestrzeń na spotkanie<br>z emocjami, ciałem i sobą.','Простір для зустрічі<br>з емоціями, тілом і собою.')}</p>${bookButton(tr('Umów sesję 1:1','Записатися на сесію 1:1'),'session','light')}</div><aside class="hero-note"><p class="note-label">${tr('SESJE 1:1 · JOGA · MEDYTACJA','СЕСІЇ 1:1 · ЙОГА · МЕДИТАЦІЯ')}</p><h2>${tr('Czas czuć.','Час відчувати.')}</h2><p class="note-copy">${tr('W swoim tempie.','У власному темпі.')}</p><span class="note-rule" aria-hidden="true"></span></aside></section><section class="philosophy"><h2><span>${tr('Nie musisz mieć wszystkiego poukładanego,','Не обов’язково мати відповіді на все,')}</span> <span class="soft">${tr('żeby zacząć słuchać siebie.','щоб почати слухати себе.')}</span></h2></section>`;}
