const dateText=d=>new Intl.DateTimeFormat(lang==='uk'?'uk-UA':'pl-PL',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Warsaw'}).format(new Date(d+'T12:00:00+01:00'));
const img=(name,alt,cls='')=>`<img class="${cls}" src="/assets/${name}" alt="${esc(alt)}" loading="lazy" decoding="async">`;
const detail=(id,title,body)=>`<details id="${id}"><summary>${title}<span class="plus" aria-hidden="true"></span></summary><div class="detail-body">${body}</div></details>`;
function eventCard(e,compact=false){const ended=e.status==='ended';return `<article class="event-card ${compact?'compact':''}">${compact?'':img(e.img,e[lang])}<div class="event-content"><div class="event-meta"><span>${tr('Przykładowa data','Приклад дати')}</span><time datetime="${e.date}">${dateText(e.date)}</time></div><h3>${e[lang]}</h3><p>${e.format==='online'?tr('Spotkanie online','Зустріч онлайн'):tr('Praktyka w studio','Практика у студії')}</p><div class="event-bottom"><span class="status ${ended?'ended':''}">${ended?tr('Zakończone','Завершено'):e.status==='soon'?tr('Zapisy wkrótce','Запис незабаром'):tr('Przykład otwartego zapisu','Приклад відкритого запису')}</span>${ended?`<button class="text-link" data-info="archive">${tr('Zobacz opis','Переглянути опис')}</button>`:`<button class="round-link" data-book="${e.service}" data-event="${e.id}" aria-label="${esc(tr('Zapytaj o: ','Запитати про: ')+e[lang])}">${arrow}</button>`}</div></div></article>`;}
// Home V1 blocks. Client edit 12.11.2026: Terapia, Szkoła Klarowności, Wydarzenia and Blog are hidden from the page.
