const homeBlocks={
about:()=>`<section id="o-mnie" class="section container about"><div class="portrait-wrap">${img('agnieszka-portrait.jpg',tr('Agnieszka na kanapie w jasnym wnętrzu','Agnieszka на канапі у світлому просторі'))}<span class="photo-caption">${tr('Z uważnością. Po ludzku.','З увагою. По-людськи.')}</span></div><div class="section-copy"><h2>${tr('Dobrze, że jesteś.','Добре, що ти тут.')}</h2><p class="lead">${tr('Jestem Agnieszka. Towarzyszę w spotkaniu z emocjami, ciałem i własnym doświadczeniem.','Я — Agnieszka. Супроводжую в зустрічі з емоціями, тілом і власним досвідом.')}</p><p>${tr('Łączę pracę indywidualną z praktyką jogi i medytacji. Tworzę przestrzeń, w której możesz zatrzymać się, porozmawiać i poszukać własnego tempa.','Поєдную індивідуальну роботу з практикою йоги та медитації. Створюю простір, де можна зупинитися, поговорити й знайти власний темп.')}</p><div class="accordion-group">${detail('about-details',tr('Poznaj moje podejście','Дізнатися про мій підхід'),`<p>${tr('Punktem wyjścia jest rozmowa i Twoje potrzeby. Formę współpracy ustalamy wspólnie. Ten opis jest tekstem roboczym do zatwierdzenia przez Agnieszkę.','Починаємо з розмови та твоїх потреб. Формат співпраці визначаємо разом. Цей опис — робочий текст для погодження Agnieszka.')}</p>`)}</div><a class="text-link" href="#sesje">${tr('Poznaj możliwości spotkania','Переглянути формати зустрічі')}${arrow}</a></div></section>`,
sessions:()=>`<section id="sesje" class="section container editorial"><div class="section-copy"><h2>${tr('Czas tylko<br>dla Ciebie.','Час лише<br>для тебе.')}</h2><p class="lead">${tr('Sesje indywidualne 1:1','Індивідуальні сесії 1:1')}</p><p>${tr('Nie musisz wiedzieć, od czego zacząć. Pierwszy krok to krótka wiadomość. Wspólnie ustalimy, jaki rodzaj spotkania odpowiada Twoim potrzebom.','Не обов’язково знати, з чого почати. Перший крок — коротке повідомлення. Разом визначимо, який формат зустрічі відповідає твоїм потребам.')}</p><div class="accordion-group">${detail('session-first',tr('Jak wygląda pierwszy krok?','Як зробити перший крок?'),`<p>${tr('Wybierz usługę w formularzu lub poproś o pomoc w wyborze. Termin, miejsce i szczegóły spotkania potwierdzimy w osobnym kontakcie.','Вибери послугу у формі або попроси допомоги з вибором. Час, місце та подробиці зустрічі підтвердимо під час окремого контакту.')}</p>`)}${detail('session-format',tr('Online czy stacjonarnie?','Онлайн чи наживо?'),`<p>${tr('Dostępny format, czas trwania i warunki ustalimy przed spotkaniem. Aktualne szczegóły zostaną uzupełnione w finalnej wersji strony.','Доступний формат, тривалість та умови узгодимо перед зустріччю. Актуальні подробиці додамо у фінальну версію сайту.')}</p>`)}</div>${bookButton(tr('Zapytaj o sesję 1:1','Запитати про сесію 1:1'),'session')}</div>${img('brainspotting.jpg',tr('Indywidualne spotkanie w jasnym gabinecie','Індивідуальна зустріч у світлому кабінеті'),'editorial-photo')}</section>`,
therapy:()=>`<section id="terapia" class="section therapy container"><div class="section-heading"><h2>${tr('Blisko emocji.<br>Blisko siebie.','Ближче до емоцій.<br>Ближче до себе.')}</h2><p>${tr('Poznaj dwa kierunki pracy indywidualnej. Rozwiń opis, by dowiedzieć się więcej i zapytać o spotkanie.','Дізнайся про два напрями індивідуальної роботи. Розгорни опис, щоб прочитати більше й запитати про зустріч.')}</p></div><div class="therapy-layout">${img('agnieszka-meditation.jpg',tr('Agnieszka podczas medytacji na łonie natury','Agnieszka під час медитації на природі'))}<div class="therapy-list"><article><h3>Brainspotting</h3><p>${tr('Indywidualna praca z doświadczeniem, emocjami i sygnałami z ciała.','Індивідуальна робота з досвідом, емоціями та сигналами тіла.')}</p><div class="accordion-group">${detail('brain-details',tr('Na czym polega spotkanie?','Як відбувається зустріч?'),`<p>${tr('Podczas kontaktu omówimy, z czym przychodzisz i jak może wyglądać sesja. Przed rozpoczęciem wyjaśnimy metodę i odpowiemy na pytania.','Під час контакту обговоримо твій запит і те, як може відбуватися сесія. Перед початком пояснимо метод і відповімо на запитання.')}</p>`)}</div><button class="text-link" data-book="brainspotting">${tr('Zapytaj o Brainspotting','Запитати про Brainspotting')}${arrow}</button></article><article><h3>Energy Mind Healing</h3><p>${tr('Praktyka obecna w ofercie Agnieszki, łącząca uwagę na ciało, oddech i osobiste doświadczenie.','Практика з пропозиції Agnieszka, що поєднує увагу до тіла, дихання та особистого досвіду.')}</p><div class="accordion-group">${detail('energy-details',tr('Dowiedz się więcej','Дізнатися більше'),`<p>${tr('Zakres i przebieg spotkania zostaną wyjaśnione w rozmowie. Szczegółowy opis metody wymaga zatwierdzenia przed publikacją strony.','Зміст і перебіг зустрічі пояснимо під час розмови. Докладний опис методу потребує погодження перед публікацією сайту.')}</p>`)}</div><button class="text-link" data-book="energy">${tr('Zapytaj o spotkanie','Запитати про зустріч')}${arrow}</button></article></div></div></section>`,
yoga:()=>`<section id="joga" class="section wide color-split mint">${img('joga.jpg',tr('Praktyka jogi w jasnym studio','Практика йоги у світлій студії'))}<div class="section-copy"><h2>${tr('Ruch. Oddech.<br>Obecność.','Рух. Дихання.<br>Присутність.')}</h2><p class="lead">Studio Jogi</p><p>${tr('Wybierz praktykę, która jest Ci bliska. Mniej pośpiechu, więcej miejsca na własne doświadczenie.','Вибери практику, яка тобі близька. Менше поспіху, більше місця для власного досвіду.')}</p><div class="accordion-group">${['kundalini','flow','combo'].map(id=>detail('yoga-'+id,label(id),`<p>${id==='kundalini'?tr('Praktyka łącząca ruch, oddech i medytację.','Практика, що поєднує рух, дихання й медитацію.'):id==='flow'?tr('Płynna praktyka ruchu i oddechu.','Плавна практика руху та дихання.'):tr('Połączenie dwóch stylów praktyki.','Поєднання двох стилів практики.')}</p><button class="text-link" data-book="${id}">${tr('Zapytaj o praktykę','Запитати про практику')}${arrow}</button>`)).join('')}</div></div></section>`,
upcoming:()=>`<section id="najblizsze" class="section container"><div class="section-heading"><h2>${tr('Spotkajmy się.','Зустріньмося.')}</h2><p>${tr('Najbliższe wydarzenia z kalendarza. W prototypie — przykładowe dane w miejscu wtyczki.','Найближчі події з календаря. У прототипі — демонстраційні дані на місці віджета.')}</p></div><div class="events-grid upcoming">${events.filter(e=>e.status!=='ended').map(e=>eventCard(e,true)).join('')}</div></section>`,
workshops:()=>`<section id="warsztaty" class="section container workshop-feature"><div class="section-copy"><h2>${tr('Odkrywaj.<br>Doświadczaj.','Відкривай.<br>Відчувай.')}</h2><p class="lead">${tr('Warsztaty i wspólna praktyka','Воркшопи та спільна практика')}</p><p>${tr('Programy, które zapraszają do refleksji, rozmowy i spotkania z własnym doświadczeniem. Poznaj wszystkie kierunki.','Програми, що запрошують до роздумів, розмови та зустрічі з власним досвідом. Дізнайся про всі напрями.')}</p><ul class="program-index">${programs.map(p=>`<li><a href="/warsztaty/#${p.id}">${label(p.id)}${arrow}</a></li>`).join('')}</ul><a class="button" href="/warsztaty/">${tr('Zobacz warsztaty','Переглянути воркшопи')}</a></div><figure>${img('workshop.jpg',tr('Swobodny ruch na plaży o zachodzie słońca','Вільний рух на пляжі під час заходу сонця'))}<figcaption class="straw"><h3>${tr('Odkryj siebie.','Відкрий себе.')}</h3><p>${tr('Cykl 12 warsztatów.','Цикл із 12 воркшопів.')}</p></figcaption></figure></section>`,
school:()=>`<section id="szkola" class="section wide school lavender"><div class="section-copy"><h2>${tr('Szkoła<br>Klarowności.','Школа<br>ясності.')}</h2><p class="lead">${tr('Miejsce na głębszą praktykę i naukę.','Місце для глибшої практики й навчання.')}</p><p>${tr('Poznaj kierunek edukacyjny Agnieszki. Napisz, jeśli chcesz otrzymać informacje o programie i kolejnych spotkaniach.','Дізнайся про навчальний напрям Agnieszka. Напиши, якщо хочеш отримати інформацію про програму й наступні зустрічі.')}</p>${bookButton(tr('Zapytaj o program','Запитати про програму'),'school')}</div>${img('agnieszka-beach.jpg',tr('Agnieszka praktykuje jogę na plaży','Agnieszka практикує йогу на пляжі'))}</section>`,
events:()=>`<section id="wydarzenia" class="section container"><div class="section-heading"><h2>${tr('Wspólne<br>doświadczenia.','Спільний<br>досвід.')}</h2><p>${tr('Wydarzenia online, praktyki i spotkania. Pokazane terminy są przykładowe.','Онлайн-події, практики й зустрічі. Показані дати — приклади.')}</p></div><div class="filter-row" aria-label="${tr('Filtruj wydarzenia','Фільтрувати події')}"><button class="filter active" data-event-filter="all" aria-pressed="true">${tr('Wszystkie','Усі')}</button><button class="filter" data-event-filter="online" aria-pressed="false">Online</button><button class="filter" data-event-filter="studio" aria-pressed="false">${tr('W studio','У студії')}</button><button class="filter" data-event-filter="ended" aria-pressed="false">${tr('Archiwum','Архів')}</button></div><div class="events-grid event-results">${events.map(e=>eventCard(e)).join('')}</div></section>`,
blog:()=>`<section id="blog" class="section container blog"><div class="section-heading"><h2>${tr('Chwila<br>na refleksję.','Хвилина<br>для роздумів.')}</h2><p>${tr('Blog — podgląd tematów z materiałów. Teksty robocze.','Блог — огляд тем із матеріалів. Робочі тексти.')}</p></div><div class="blog-grid">${[['joga.jpg',tr('Ruch, oddech i chwila dla siebie','Рух, дихання та хвилина для себе')],['brainspotting.jpg',tr('Jak przygotować się do pierwszej rozmowy','Як підготуватися до першої розмови')],['agnieszka-meditation.jpg',tr('Uważność w codzienności','Усвідомленість у щоденному житті')]].map(([photo,title],i)=>`<button class="blog-card" data-info="article-${i}">${img(photo,title)}<span>${tr('Materiał w przygotowaniu','Матеріал готується')}</span><h3>${title}</h3><span class="blog-arrow">${arrow}</span></button>`).join('')}</div></section>`,
shop:()=>shopTeaser()
};
const homeOrder=['about','sessions','yoga','workshops','upcoming'];
function homeSections(){return homeOrder.map(k=>homeBlocks[k]()).join('');}
function contact(){return `<section id="kontakt" class="section wide contact straw"><div class="section-copy"><h2>${tr('Zacznijmy<br>od rozmowy.','Почнімо<br>з розмови.')}</h2><p>${tr('Nie musisz od razu wybierać metody. Napisz, a wspólnie ustalimy pierwszy krok.','Не обов’язково одразу вибирати метод. Напиши — і разом визначимо перший крок.')}</p>${bookButton(tr('Napisz do mnie','Написати мені'))}</div>${img('agnieszka-portrait.jpg',tr('Portret Agnieszki','Портрет Agnieszka'))}</section>`;}
function footer(){return `<footer class="site-footer"><div class="footer-top"><div><a class="brand" href="/#top">agnieszka clarity</a><p>${tr('Przestrzeń na spotkanie<br>z emocjami, ciałem i sobą.','Простір для зустрічі<br>з емоціями, тілом і собою.')}</p></div><nav aria-label="${tr('Oferta','Послуги')}"><h3>${tr('Spotkania','Зустрічі')}</h3><a href="/#sesje">${tr('Sesje 1:1','Сесії 1:1')}</a><a href="/#joga">${tr('Studio Jogi','Студія йоги')}</a><a href="/warsztaty/">${tr('Warsztaty','Воркшопи')}</a><a href="/#najblizsze">${tr('Wydarzenia','Події')}</a></nav><nav aria-label="${tr('Informacje','Інформація')}"><h3>${tr('Warto wiedzieć','Корисне')}</h3><a href="/#kontakt">${tr('Kontakt','Контакт')}</a><a href="/sklep/">${tr('Sklep','Магазин')}</a><button data-info="rules">${tr('Regulamin','Правила')}</button><button data-info="privacy">${tr('Polityka prywatności','Конфіденційність')}</button></nav><div class="footer-events"><h3>${tr('Najbliższe spotkanie','Найближча зустріч')}</h3><p class="demo-caption">${tr('Przykład w prototypie','Приклад у прототипі')}</p><button data-book="${events[0].service}" data-event="${events[0].id}"><time datetime="${events[0].date}">${dateText(events[0].date)}</time><span>${events[0][lang]} ${arrow}</span></button></div></div><div class="footer-bottom"><span>© 2026 agnieszka clarity</span><span>${tr('Prototyp do uzgodnienia · Bez zakupów i wysyłki danych','Прототип для погодження · Без покупок і надсилання даних')}</span></div><p class="footer-word" aria-hidden="true">clarity.</p></footer>`;}
function workshopsPage(){const v2=version==='2';return `${v2?v2PageHero('workshops'):`<section class="page-intro container"><h1>${tr('Przestrzeń<br>do odkrywania.','Простір<br>для відкриттів.')}</h1><div><p class="lead">${tr('Warsztaty','Воркшопи')}</p><p>${tr('Praktyka, refleksja i wspólne doświadczenie. Poznaj programy i znajdź temat, który jest Ci teraz bliski.','Практика, роздуми та спільний досвід. Переглянь програми й знайди тему, яка зараз тобі близька.')}</p></div></section>`}<nav id="programy" class="program-jumps container" aria-label="${tr('Programy warsztatów','Програми воркшопів')}">${v2?v2Label('Programy','Програми'):''}${programs.map(p=>`<a href="#${p.id}">${label(p.id)}${arrow}</a>`).join('')}</nav><div class="programs container">${programs.map((p,i)=>`<section id="${p.id}" class="program-section ${i%2?'reverse':''}"><div class="program-photo ${p.tone}">${img(p.img,label(p.id))}</div><div class="section-copy"><h2>${label(p.id)}</h2><p class="lead">${p[lang]}</p><p class="availability">${tr('Termin i szczegóły do ustalenia','Дату й подробиці узгодимо окремо')}</p><div class="accordion-group">${detail(p.id+'-program',tr('Program warsztatu','Програма воркшопу'),`<p>${tr('Wprowadzenie do tematu, wspólna praktyka, czas na pytania i samodzielną refleksję. Dokładny program zostanie zatwierdzony przed publikacją.','Вступ до теми, спільна практика, час для запитань і самостійних роздумів. Точну програму буде погоджено перед публікацією.')}</p>`)}${detail(p.id+'-audience',tr('Dla kogo?','Для кого?'),`<p>${tr('Dla osób zainteresowanych tym tematem. Przed zgłoszeniem możesz zapytać o format, wymagania i przebieg spotkania.','Для тих, хто цікавиться цією темою. Перед заявкою можна запитати про формат, вимоги та перебіг зустрічі.')}</p>`)}</div>${bookButton(tr('Zapytaj o udział','Запитати про участь'),p.id)}</div></section>`).join('')}</div><section class="container section"><div class="section-heading"><h2>${tr('Praktyka<br>w dobrym towarzystwie.','Практика<br>у доброму товаристві.')}</h2><p>${tr('Przykładowe nadchodzące wydarzenia.','Приклади найближчих подій.')}</p></div>${v2?`<div class="v2-event-list">${v2EventRows(events.filter(e=>e.status!=='ended'))}</div>`:`<div class="events-grid">${events.slice(0,3).map(e=>eventCard(e,true)).join('')}</div>`}</section>`;}
// ---- Shop (demo catalog, no purchases) -------------------------------------------------
// Prices come from the client's "Sklep v1.pdf" mock and are shown as examples only.
const shopIcons={
 screen:'<rect x="3" y="4.5" width="18" height="12" rx="1.5"/><path d="M8.5 20h7M12 16.5V20M7 8.5h6M7 11.5h10"/>',
 lotus:'<path d="M12 4.5c-2.6 3-2.6 8.2 0 12.5 2.6-4.3 2.6-9.5 0-12.5Z"/><path d="M12 17c-4.2 0-7.6-2.4-9-6 3.6-.4 6.8 1.6 9 6Zm0 0c4.2 0 7.6-2.4 9-6-3.6-.4-6.8 1.6-9 6Z"/><path d="M5 20h14"/>',
 book:'<path d="M12 6.5C10 5 7 4.5 3.5 5v13c3.5-.5 6.5 0 8.5 1.5 2-1.5 5-2 8.5-1.5V5C17 4.5 14 5 12 6.5Z"/><path d="M12 6.5v13"/>'
};
const shopIcon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linejoin="round" stroke-linecap="round">${shopIcons[name]}</svg>`;
const shopCats=[
 {id:'all',pl:'Wszystko',uk:'Усе'},
 {id:'workshops',pl:'Warsztaty online',uk:'Онлайн-воркшопи',icon:'screen',format:{pl:'Warsztat online',uk:'Онлайн-воркшоп'}},
 {id:'yoga',pl:'Joga',uk:'Йога',icon:'lotus',format:{pl:'Praktyka jogi',uk:'Практика йоги'}},
 {id:'ebooks',pl:'E-booki',uk:'Електронні книги',icon:'book',format:{pl:'E-book',uk:'Електронна книга'}}
];
const products=[
 {id:'discover',cat:'workshops',price:250},
 {id:'mantra',cat:'yoga',price:280,pl:'Doświadczenie jogi kundalini poprzez dźwięk, mantrę i medytację.',uk:'Досвід кундаліні-йоги через звук, мантру й медитацію.'},
 {id:'mind',cat:'workshops',price:240},
 {id:'life',cat:'workshops',price:250},
 {id:'kundalini',cat:'yoga',price:240,pl:'Praktyka łącząca ruch, oddech i medytację. Dla osób, które chcą poczuć więcej energii i spokoju.',uk:'Практика, що поєднує рух, дихання й медитацію. Для тих, хто хоче відчути більше енергії та спокою.'},
 {id:'money',cat:'workshops',price:240}
];
const catOf=p=>shopCats.find(c=>c.id===p.cat);
const productText=p=>p[lang]||programs.find(x=>x.id===p.id)?.[lang]||'';
const priceText=n=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN',maximumFractionDigits:0}).format(n);
const countText=n=>{const r=new Intl.PluralRules(lang==='uk'?'uk-UA':'pl-PL').select(n);const w=lang==='uk'?{one:'продукт',few:'продукти',many:'продуктів',other:'продукту'}:{one:'produkt',few:'produkty',many:'produktów',other:'produktu'};return `${n} ${w[r]}`;};
const productUrl=id=>`/sklep/?produkt=${encodeURIComponent(id)}`;
function shopFilterKey(){let k='all';try{k=new URLSearchParams(location.search).get('kategoria')||'all';}catch{}return shopCats.some(c=>c.id===k)?k:'all';}
function productMedia(p,size=''){const c=catOf(p);return `<div class="product-media ${size}"><span class="product-badge">${c.format[lang]}</span>${shopIcon(c.icon,'product-icon')}<span class="visually-hidden">${tr('Miejsce na zdjęcie produktu','Місце для фото продукту')}</span></div>`;}
function productCard(p,h='h2'){return `<article class="product-card">${productMedia(p)}<div class="product-body"><${h} class="product-title"><a href="${productUrl(p.id)}">${label(p.id)}</a></${h}><p class="product-desc">${productText(p)}</p><div class="product-foot"><p class="product-price"><span class="price">${priceText(p.price)}</span><span class="price-note">${tr('Cena przykładowa','Приклад ціни')}</span></p><span class="product-go" aria-hidden="true">${arrow}</span></div></div></article>`;}
function shopProducts(filter,limit=99,h='h2'){const list=products.filter(p=>filter==='all'||p.cat===filter).slice(0,limit);return list.length?list.map(p=>productCard(p,h)).join(''):`<div class="empty-state">${shopIcon('book','empty-icon')}<h2>${tr('Jeszcze chwila.','Ще трохи.')}</h2><p>${tr('E-booki pojawią się w sklepie wkrótce. Zajrzyj do warsztatów online albo praktyk jogi.','Електронні книги з’являться в магазині незабаром. Переглянь онлайн-воркшопи або практики йоги.')}</p><button class="text-link" data-shop-filter="all">${tr('Zobacz cały katalog','Переглянути весь каталог')}${arrow}</button></div>`;}
function shopToolbar(active){const n=products.filter(p=>active==='all'||p.cat===active).length;return `<div class="shop-toolbar"><div class="filter-row" role="group" aria-label="${tr('Kategorie katalogu','Категорії каталогу')}">${shopCats.map(c=>`<button class="filter ${c.id===active?'active':''}" data-shop-filter="${c.id}" aria-pressed="${c.id===active}">${c[lang]}</button>`).join('')}</div><p class="shop-count" aria-live="polite">${countText(n)}</p></div>`;}
function shopPage(){const k=shopFilterKey();return `${version==='2'?v2PageHero('shop'):`<section class="page-intro container"><h1>${tr('Dobre rzeczy<br>dla siebie.','Добрі речі<br>для себе.')}</h1><div><p class="lead">${tr('Sklep','Магазин')}</p><p>${tr('Warsztaty online i praktyki do wykonania w swoim tempie. Katalog pokazowy: zakupy online nie są jeszcze dostępne.','Онлайн-воркшопи та практики у власному темпі. Демонстраційний каталог: онлайн-покупки поки недоступні.')}</p></div></section>`}<section id="katalog" class="container shop-section">${shopToolbar(k)}<div class="shop-grid">${shopProducts(k)}</div><p class="catalog-note">${tr('Ceny i produkty są przykładowe — pochodzą z makiety sklepu. Dostępność i oferta zostaną potwierdzone osobno.','Ціни й продукти — приклади з макета магазину. Наявність і пропозицію підтвердимо окремо.')}</p></section>`;}
function applyShopFilter(key){$$('[data-shop-filter]').forEach(b=>{if(!b.closest('.filter-row'))return;b.classList.toggle('active',b.dataset.shopFilter===key);b.setAttribute('aria-pressed',String(b.dataset.shopFilter===key));});$('.shop-grid').innerHTML=shopProducts(key);const n=products.filter(p=>key==='all'||p.cat===key).length;const count=$('.shop-count');if(count)count.textContent=countText(n);try{const url=new URL(location.href);key==='all'?url.searchParams.delete('kategoria'):url.searchParams.set('kategoria',key);history.replaceState(null,'',url);}catch{}}
function shopProductId(){try{return new URLSearchParams(location.search).get('produkt');}catch{return null;}}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return `<section class="container product-missing"><h1>${tr('Nie znaleźliśmy<br>tego produktu.','Не вдалося знайти<br>цей продукт.')}</h1><p>${tr('Mógł zostać usunięty z katalogu albo adres jest niepełny.','Можливо, його прибрали з каталогу або адреса неповна.')}</p><a class="button" href="/sklep/">${tr('Wróć do sklepu','Повернутися до магазину')}<span class="arrow">${arrow}</span></a></section>`;
 const c=catOf(p),title=label(p.id),bookable=services.some(s=>s.id===p.id);
 document.title=`${title} — ${tr('Sklep','Магазин')} — agnieszka clarity`;
 const includes=p.cat==='yoga'?[tr('Praktyka prowadzona przez Agnieszkę','Практика під проводом Agnieszka'),tr('Wskazówki do samodzielnej praktyki w domu','Поради для самостійної практики вдома'),tr('Możliwość zadania pytań przed zakupem','Можливість поставити запитання до покупки')]:[tr('Udział w warsztacie online','Участь в онлайн-воркшопі'),tr('Materiały do pracy własnej','Матеріали для самостійної роботи'),tr('Czas na pytania i refleksję','Час для запитань і роздумів')];
 const related=products.filter(x=>x.id!==p.id).sort((a,b)=>(b.cat===p.cat)-(a.cat===p.cat)).slice(0,3);
 return `<nav class="container breadcrumbs" aria-label="${tr('Ścieżka','Навігаційний шлях')}"><ol><li><a href="/sklep/">${tr('Sklep','Магазин')}</a></li><li><a href="/sklep/?kategoria=${p.cat}">${c[lang]}</a></li><li aria-current="page">${title}</li></ol></nav>
<section class="container product-detail"><div class="product-gallery">${productMedia(p,'large')}<p class="gallery-note">${tr('Miejsce na zdjęcia produktu','Місце для фото продукту')}</p></div>
<div class="product-buy"><h1>${title}</h1><p class="product-lead">${productText(p)}</p>
<div class="buy-price"><span class="price">${priceText(p.price)}</span><span class="price-note">${tr('Cena przykładowa z makiety','Приклад ціни з макета')}</span></div>
<p class="availability-line"><span class="dot" aria-hidden="true"></span>${tr('Sprzedaż online wkrótce. Możesz już teraz zapytać o termin i dostęp.','Онлайн-продаж незабаром. Вже зараз можна запитати про дату й доступ.')}</p>
<button class="button buy-cta" data-book="${bookable?p.id:'help'}">${tr('Zapytaj o ten produkt','Запитати про цей продукт')}<span class="arrow">${arrow}</span></button>
<dl class="product-facts"><div><dt>${tr('Format','Формат')}</dt><dd>${c.format[lang]}</dd></div><div><dt>${tr('Kategoria','Категорія')}</dt><dd>${c[lang]}</dd></div><div><dt>${tr('Prowadzenie','Проводить')}</dt><dd>Agnieszka</dd></div><div><dt>${tr('Termin i dostęp','Дата й доступ')}</dt><dd>${tr('Do potwierdzenia','Буде підтверджено')}</dd></div></dl></div></section>
<section class="container product-info"><div><h2>${tr('O produkcie','Про продукт')}</h2><p>${productText(p)} ${tr('Pełny opis, program i forma dostępu zostaną uzupełnione przed uruchomieniem sprzedaży.','Повний опис, програму й формат доступу додамо перед запуском продажу.')}</p></div><div><h2>${tr('Co otrzymasz','Що ти отримаєш')}</h2><ul>${includes.map(i=>`<li>${i}</li>`).join('')}</ul><p class="demo-caption">${tr('Przykładowa zawartość — do zatwierdzenia.','Приклад наповнення — потребує погодження.')}</p></div><div><h2>${tr('Dla kogo?','Для кого?')}</h2><p>${tr('Dla osób zainteresowanych tym tematem. Przed zgłoszeniem możesz zapytać o format, wymagania i przebieg.','Для тих, хто цікавиться цією темою. Перед заявкою можна запитати про формат, вимоги та перебіг.')}</p></div></section>
<section class="container section related"><div class="section-heading"><h2>${tr('Może Cię też<br>zainteresować.','Тебе також<br>може зацікавити.')}</h2><a class="text-link" href="/sklep/">${tr('Cały katalog','Весь каталог')}${arrow}</a></div><div class="shop-grid">${related.map(x=>productCard(x,'h3')).join('')}</div></section>`;}
function shopTeaser(){return `<section id="sklep" class="section container shop-teaser"><div class="section-heading"><h2>${tr('Dobre rzeczy<br>dla siebie.','Добрі речі<br>для себе.')}</h2><p>${tr('Warsztaty online i praktyki do wykonania w swoim tempie. Katalog pokazowy, zakupy online nie są jeszcze dostępne.','Онлайн-воркшопи та практики у власному темпі. Демонстраційний каталог, онлайн-покупки поки недоступні.')}</p></div><div class="shop-grid">${shopProducts('all',3,'h3')}</div><a class="button shop-teaser-cta" href="/sklep/">${tr('Zobacz sklep','Переглянути магазин')}<span class="arrow">${arrow}</span></a></section>`;}
let draft={name:'',email:'',phone:'',service:'help',event:'',message:''};
let opener=null,sendTimer=null;
function eventOptions(){const compatible=events.filter(e=>e.service===draft.service&&e.status!=='ended');return `<option value="">${tr('Bez konkretnego terminu','Без конкретної дати')}</option>`+compatible.map(e=>`<option value="${e.id}" ${draft.event===e.id?'selected':''}>${esc(e[lang])} — ${dateText(e.date)} (${tr('przykład','приклад')})</option>`).join('');}
function dialogs(){return `<dialog id="booking" aria-labelledby="booking-title"><div class="dialog-head"><button class="dialog-language" data-language>${tr('Українською','Po polsku')}</button><button class="close" data-close="booking" aria-label="${tr('Zamknij formularz','Закрити форму')}"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="booking-body"><h2 id="booking-title">${tr('Zacznijmy<br>od rozmowy.','Почнімо<br>з розмови.')}</h2><p class="form-intro">${tr('Wybierz usługę. Szczegóły spotkania ustalimy wspólnie.','Вибери послугу. Подробиці зустрічі узгодимо разом.')}</p><p class="form-demo">${tr('Tryb demonstracyjny — dane nie są wysyłane.','Демонстраційний режим — дані не надсилаються.')}</p><form id="booking-form" novalidate><div class="field"><label for="service">${tr('Wybierz usługę','Вибери послугу')}</label><select id="service" name="service">${services.map(s=>`<option value="${s.id}" ${draft.service===s.id?'selected':''}>${esc(s[lang])}</option>`).join('')}</select></div><div class="field" id="event-field" ${events.some(e=>e.service===draft.service&&e.status!=='ended')?'':'hidden'}><label for="event">${tr('Wydarzenie / termin','Подія / дата')}</label><select id="event" name="event">${eventOptions()}</select></div><div class="field"><label for="name">${tr('Imię i nazwisko','Ім’я та прізвище')} <span aria-hidden="true">*</span></label><input id="name" name="name" autocomplete="name" required maxlength="120" value="${esc(draft.name)}" aria-describedby="name-error"><p class="field-error" id="name-error" hidden></p></div><div class="field"><label for="email">${tr('Adres e-mail','Електронна пошта')} <span aria-hidden="true">*</span></label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254" value="${esc(draft.email)}" aria-describedby="email-error"><p class="field-error" id="email-error" hidden></p></div><div class="field"><label for="phone">${tr('Telefon (opcjonalnie)','Телефон (необов’язково)')}</label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40" value="${esc(draft.phone)}"></div><div class="field"><label for="message">${tr('Wiadomość (opcjonalnie)','Повідомлення (необов’язково)')}</label><textarea id="message" name="message" rows="3" maxlength="1500" aria-describedby="message-help">${esc(draft.message)}</textarea><p id="message-help" class="field-help">${tr('Wystarczy pytanie organizacyjne. Nie wpisuj danych o zdrowiu.','Достатньо організаційного запитання. Не вказуй дані про здоров’я.')}</p></div><p class="form-terms">${tr('Wysłanie formularza nie potwierdza terminu spotkania.','Надсилання форми не підтверджує час зустрічі.')} <button type="button" class="inline-link" data-info="privacy">${tr('Informacja o prywatności','Інформація про приватність')}</button></p><button class="button submit-button" type="submit">${tr('Sprawdź zgłoszenie','Перевірити заявку')}<span class="arrow">${arrow}</span></button></form><div class="form-success" role="status" hidden><span class="success-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m5 12 4 4L19 6"/></svg></span><h3>${tr('Tak będzie wyglądać<br>potwierdzenie.','Так виглядатиме<br>підтвердження.')}</h3><p>${tr('To tylko demonstracja. Żadne dane nie zostały wysłane. W finalnej wersji zgłoszenie trafi na ustalony adres e-mail.','Це лише демонстрація. Жодні дані не були надіслані. У фінальній версії заявка надійде на узгоджену електронну адресу.')}</p><button class="button" data-close="booking">${tr('Wróć do strony','Повернутися до сайту')}</button></div></div></dialog><dialog id="information" aria-labelledby="info-title"><div class="dialog-head"><button class="close" data-close="information" aria-label="${tr('Zamknij','Закрити')}"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="info-body"><h2 id="info-title"></h2><p id="info-copy"></p><button class="button" data-close="information">${tr('Rozumiem','Зрозуміло')}</button></div></dialog>`;}
function captureDraft(){const f=$('#booking-form');if(f&&!f.hidden)for(const k of Object.keys(draft)){const el=f.elements.namedItem(k);if(el)draft[k]=el.value;}}
function openBooking(id,event=''){captureDraft();$('.mobile-nav')?.classList.remove('open');$('.menu-toggle')?.setAttribute('aria-expanded','false');draft.service=services.some(s=>s.id===id)?id:'help';draft.event=events.some(e=>e.id===event&&e.service===draft.service&&e.status!=='ended')?event:'';opener=document.activeElement;$('#booking').remove();$('#information').remove();$('#app').insertAdjacentHTML('beforeend',dialogs());$('#booking').showModal();document.body.classList.add('dialog-open');$('#service').focus();}
function closeDialog(id){if(id==='booking'){clearTimeout(sendTimer);captureDraft();}$('#'+id).close();if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open');if(id==='booking'&&opener?.isConnected)opener.focus();}
function openInfo(id){const privacy=id==='privacy',rules=id==='rules';$('#info-title').textContent=privacy?tr('Prywatność','Приватність'):rules?tr('Regulamin','Правила'):tr('Materiał w przygotowaniu','Матеріал готується');$('#info-copy').textContent=privacy?tr('Ten lokalny prototyp nie wysyła danych z formularza. Przechowuje w przeglądarce wyłącznie wybór języka i wersji wyglądu. Finalna informacja o przetwarzaniu danych zostanie dodana przed uruchomieniem zapisów.','Цей локальний прототип не надсилає дані форми. У браузері зберігається лише вибір мови й версії дизайну. Остаточну інформацію про обробку даних додамо перед запуском запису.'):rules?tr('Tutaj znajdzie się zatwierdzony regulamin. W prototypie nie są zawierane umowy ani dokonywane zakupy.','Тут будуть погоджені правила. У прототипі договори не укладаються й покупки не здійснюються.'):tr('To podgląd miejsca na artykuł lub opis archiwalnego wydarzenia. Treść zostanie uzupełniona i zatwierdzona przed publikacją.','Це огляд місця для статті або опису архівної події. Текст буде додано й погоджено перед публікацією.');$('#information').showModal();document.body.classList.add('dialog-open');}
function versionSwitcher(){return `<nav class="version-switch" aria-label="${tr('Wersja wyglądu strony','Версія вигляду сайту')}"><span>${tr('Wersja','Версія')}</span>${['1','2'].map(v=>`<a href="${location.pathname}?v=${v}&lang=${lang}" data-version="${v}" ${version===v?'aria-current="true"':''} aria-label="${tr('Otwórz wersję ','Відкрити версію ')}${v}">V${v}</a>`).join('')}</nav>`;}
function render(){const isWorkshop=location.pathname.startsWith('/warsztaty'),isShop=location.pathname.startsWith('/sklep'),theme2=version==='2',v2=theme2&&!isWorkshop&&!isShop;document.body.classList.toggle('inner-page',isWorkshop||isShop);document.body.classList.toggle('version-two',theme2);document.body.classList.toggle('product-view',isShop&&!!shopProductId());document.documentElement.lang=lang;document.title=tr('Agnieszka clarity — przestrzeń dla Ciebie','Agnieszka clarity — простір для себе');$('#app').innerHTML=(theme2?headerV2():header())+`<main id="main">${isWorkshop?workshopsPage():isShop?(shopProductId()?productPage(shopProductId()):shopPage()):v2?homeHeroV2()+homeSectionsV2():homeHero()+homeSections()}${theme2?contactV2():contact()}</main>`+footer()+versionSwitcher()+(v2&&typeof heroSwitcher==='function'?heroSwitcher():'')+dialogs();}
function setLanguage(){const bookingOpen=$('#booking')?.open,finished=$('.form-success')&&!$('.form-success').hidden;clearTimeout(sendTimer);captureDraft();const openDetails=$$('details[open]').map(x=>x.id);const y=scrollY;lang=lang==='pl'?'uk':'pl';try{localStorage.setItem('agnieszka-language',lang);}catch{}const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);render();openDetails.forEach(id=>{const el=document.getElementById(id);if(el)el.open=true;});window.scrollTo({top:y,behavior:'instant'});if(bookingOpen){$('#booking').showModal();document.body.classList.add('dialog-open');if(finished){$('#booking-form').hidden=true;$('.form-intro').hidden=true;$('.form-success').hidden=false;}$('.dialog-language').focus();}}
function setVersion(next){if(next===version)return;captureDraft();const openDetails=$$('details[open]').map(x=>x.id);const anchor=$$('main>section[id]').filter(el=>el.getBoundingClientRect().top<=120).pop();const offset=anchor?anchor.getBoundingClientRect().top:0;version=next;try{localStorage.setItem('agnieszka-home-version',version);}catch{}const url=new URL(location.href);url.searchParams.set('v',version);history.replaceState(null,'',url);render();openDetails.forEach(id=>{const el=document.getElementById(id);if(el)el.open=true;});const replacement=anchor&&document.getElementById(anchor.id);window.scrollTo({top:replacement?replacement.getBoundingClientRect().top+scrollY-offset:0,behavior:'instant'});$(`[data-version="${version}"]`).focus({preventScroll:true});}
document.addEventListener('click',e=>{
 const target=e.target;
 const variant=target.closest('[data-version]');if(variant){e.preventDefault();return setVersion(variant.dataset.version);}
 if(target.closest('[data-language]'))return setLanguage();
 const booking=target.closest('[data-book]');if(booking)return openBooking(booking.dataset.book,booking.dataset.event);
 const close=target.closest('[data-close]');if(close)return closeDialog(close.dataset.close);
 const info=target.closest('[data-info]');if(info)return openInfo(info.dataset.info);
 if(target.closest('.menu-toggle')){const open=$('.mobile-nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));return;}
 if(target.closest('.mobile-nav a')){$('.mobile-nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}
 const filter=target.closest('[data-event-filter]');if(filter){const key=filter.dataset.eventFilter;$$('[data-event-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter));});$('.event-results').innerHTML=events.filter(e=>key==='all'||(key==='ended'?e.status==='ended':e.format===key&&e.status!=='ended')).map(e=>eventCard(e)).join('');}
 const shop=target.closest('[data-shop-filter]');if(shop)applyShopFilter(shop.dataset.shopFilter);
});
document.addEventListener('change',e=>{if(e.target.id==='service'){captureDraft();draft.event='';$('#event').innerHTML=eventOptions();$('#event-field').hidden=!events.some(x=>x.service===draft.service&&x.status!=='ended');}});
document.addEventListener('toggle',e=>{if(e.target.matches('details')&&e.target.open){const group=e.target.closest('.accordion-group');if(group)$$('details[open]',group).forEach(d=>{if(d!==e.target)d.open=false;});}},true);
document.addEventListener('cancel',e=>{if(e.target.matches('dialog')){e.preventDefault();closeDialog(e.target.id);}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='booking-form')return;e.preventDefault();captureDraft();let first=null;for(const id of ['name','email']){const input=$('#'+id),error=$('#'+id+'-error');const invalid=id==='name'?!input.value.trim():!input.value.trim()||!input.validity.valid;input.setAttribute('aria-invalid',String(invalid));error.hidden=!invalid;error.textContent=id==='name'?tr('Wpisz imię i nazwisko.','Вкажи ім’я та прізвище.'):tr('Wpisz poprawny adres e-mail.','Вкажи коректну електронну адресу.');if(invalid&&!first)first=input;}if(first)return first.focus();const button=$('.submit-button');button.disabled=true;button.textContent=tr('Sprawdzanie…','Перевірка…');sendTimer=setTimeout(()=>{if(!$('#booking').open)return;$('#booking-form').hidden=true;$('.form-intro').hidden=true;$('.form-success').hidden=false;$('#booking-form').reset();draft={name:'',email:'',phone:'',service:'help',event:'',message:''};$('.form-success button').focus();},400);});
// 13.11.2026: the V2 hero entrance plays once per page load; later re-renders (language, version) show the hero at rest.
// Without JS the class never appears, so the hero is simply visible.
document.documentElement.classList.add('v2-hero-entrance');
render();
setTimeout(()=>document.documentElement.classList.remove('v2-hero-entrance'),3200);
